Theorem head : PMB.locale_ctor_spec L ar HI ->
  forall (fx : FPState) R0 M0 model0 K LB FF LK0 Aw0 cr sp r fb oa str sm,
    PMBRS.pre L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr sp r fb oa str sm ->
    (forall (fx1 : FPState) R1 M1 model1 LK1 Aw1, PMBRS.rmid1 L ar HI R0 M0 model0 LB FF LK0 Aw0 cr sp fb R1 M1 model1 LK1 Aw1 ->
        srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx1) R1 0xb4fac M1 model1) K) ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R0 0xb4954 M0 model0) K.
Proof.
Ltac t64 AG V VIS X Ms := apply (L5C.u64_at_agree RSEGS Ms); [intros i Hi; apply AG; (lia || fail 1 "AG")| (lia || fail 1 "B1")| (lia || fail 1 "B2")|];
                            apply (PMBIS1.vis_u64 _ _ _ _ _ VIS); [apply V; (lia || fail 1 "V") | (lia || fail 1 "B3") | (lia || fail 1 "B4") | exact X].
Ltac t32 AG V VIS X Ms := apply (PMF.u32_at_agree RSEGS Ms); [intros i Hi; apply AG; (lia || fail 1 "AG32")| (lia || fail 1 "C1")| (lia || fail 1 "C2")|];
                            apply (PMBIS1.vis_u32 _ _ _ _ _ VIS); [apply V; (lia || fail 1 "V32") | (lia || fail 1 "C3") | (lia || fail 1 "C4") | exact X].
